function boardingActionSlug(title: string) {
  return title.toLowerCase().replace(/[^a-z0-9]+/g, "_").replace(/^_|_$/g, "").slice(0, 80) || "boarding_action";
}

async function persistBoardingWorkflowAction(title: string, body: string, tone: BoardingActionTone) {
  return requestDashboardApi("/api/admin-command/boarding-master/actions", {
    method: "POST",
    body: {
      action: boardingActionSlug(title),
      title,
      message: body,
      priority: tone === "danger" || tone === "warning" ? "high" : "normal",
      targetRoles: tone === "danger" || tone === "warning"
        ? ["boarding_master", "principal", "deputy_principal"]
        : ["boarding_master", "principal"],
      payload: { tone },
    },
  });
}

async function recordBoardingAction(title: string, body: string, tone: BoardingActionTone = "info") {
  try {
    await persistBoardingWorkflowAction(title, body, tone);
  } catch (error: unknown) {
    const message = error instanceof Error ? error.message : "Boarding action could not be recorded";
    toast.error(message);
    return false;
  }

  const notify = tone === "danger" ? toast.error : tone === "success" ? toast.success : toast.info;
  notify(title, { description: body });
  publishSchoolOperationalEvent({
    type: "boarding.workflow_action",
    module: "boarding",
    actorRole: "boarding_master",
    title,
    body,
  });
  return true;
}

async function openBoardingActionRecord(title: string, rows: Array<[string, string]>) {
  const persisted = await recordBoardingAction("Boarding record opened", `${title} is available for preview, print, or PDF download.`, "success");
  if (!persisted) {
    return;
  }

  openPrintDocument({
    eyebrow: "MyShule Boarding Master",
    title,
    subtitle: `School: ${getCurrentSchoolId() || "current tenant"} | Generated ${new Date().toLocaleString()}`,
    rows: rows.map(([label, value]) => ({ label, value })),
    footer: "Boarding records and reports are tenant-scoped and should be reviewed before parent or staff communication.",
  });
}

async function exportBoardingCsv(filename: string, headers: string[], rows: string[][], title: string) {
  const persisted = await recordBoardingAction("Boarding export created", `${title} was downloaded from the current boarding workspace.`, "success");
  if (!persisted) {
    return;
  }

  downloadCsvFile({ filename, headers, rows });
}

async function generateBoardingReport(reportType: string) {
  try {
    await requestDashboardApi("/admin-command/boarding-master/reports/generate", {
      method: "POST",
      body: { report_type: reportType, generated_from: "boarding-master-command-center" },
    });
    openBoardingActionRecord(reportType, [
      ["Report", reportType],
      ["Scope", "Current school tenant"],
      ["Generated from", "Boarding Master command center"],
      ["Status", "Generation requested and print preview generated"],
    ]);
  } catch (error: any) {
    recordBoardingAction("Boarding report failed", error?.message || "The report could not be generated. Check backend readiness and tenant context.", "danger");
  }
}

