function ApprovalsWorkspace() {
  const { data, refetch } = useSchoolQuery<any>("/api/admin-command/boarding-master/leave-exit");
  const [isSubmitting, setIsSubmitting] = useState(false);
  const requests = (data?.leaveexitList || []).filter((request: any) => request.status === "Pending");

  async function handleApproveBoardingRequest(request: any) {
    setIsSubmitting(true);
    try {
      await requestDashboardApi(`/api/admin-command/boarding-master/leave-exit/${request.id}/approve`, {
        method: "POST",
      });
      toast.success("Boarding approval completed");
      await refetch();
    } catch (error: unknown) {
      toast.error(error instanceof Error ? error.message : "Boarding approval could not be completed");
    } finally {
      setIsSubmitting(false);
    }
  }

  async function handleRejectBoardingRequest(request: any) {
    const reason = window.prompt(`Reason for rejecting ${request.student_name || "this boarding request"}`);
    if (!reason?.trim()) return;

    setIsSubmitting(true);
    try {
      await requestDashboardApi(`/api/admin-command/boarding-master/leave-exit/${request.id}/reject`, {
        method: "POST",
        body: { reason: reason.trim() },
      });
      toast.success("Boarding request rejected");
      await refetch();
    } catch (error: unknown) {
      toast.error(error instanceof Error ? error.message : "Boarding request could not be rejected");
    } finally {
      setIsSubmitting(false);
    }
  }

  return (
    <Panel title="Approvals" description="Boarding approvals in one clean workspace." icon={CheckCircle}>
       <DataTable 
        columns={["Request", "Student/Dorm", "Type", "Required Approver", "Status", "Actions"]}
        rows={requests.map((request: any) => [
          "Leave Request",
          request.student_name || request.hostel || "-",
          request.leave_type || "Boarding leave",
          "Deputy Principal",
          <StatusChip key="s1" label={request.status} tone="warning"/>,
          <span key="a1" className="flex gap-2">
            <button type="button" disabled={isSubmitting} className="text-emerald-700 font-bold text-xs disabled:opacity-50" onClick={() => handleApproveBoardingRequest(request)}>Approve</button>
            <button type="button" disabled={isSubmitting} className="text-rose-700 font-bold text-xs disabled:opacity-50" onClick={() => handleRejectBoardingRequest(request)}>Reject</button>
          </span>,
        ])}
      />
    </Panel>
  );
}

