// Simple Layout Components

export function BoardingMasterCommandCenter({ routeMode, activeSection }: { routeMode: RouteMode; activeSection?: string }) {
  const [activeView, setActiveView] = useState<ViewId>(
    (activeSection && activeSection !== "dashboard" ? activeSection : "overview") as ViewId
  );
  const [searchTerm, setSearchTerm] = useState("");
  const { data: searchAllocationData } = useSchoolQuery<any>("/api/admin-command/boarding-master/allocation");
  const { data: searchIncidentsData } = useSchoolQuery<any>("/api/admin-command/boarding-master/incidents");
  const searchRecords: SearchRecord[] = [
    ...asRows<any>(searchAllocationData?.allocationList ?? searchAllocationData).slice(0, 8).map((record: any) => ({
      id: `allocation-${record.id || record.student_id}`,
      label: record.student_name || record.student_id?.substring?.(0, 8) || "Boarding allocation",
      detail: `${record.hostel || record.hostel_name || "Hostel not set"} | ${record.room_number || "room not set"} | ${record.status || "active"}`,
      view: "register" as ViewId,
    })),
    ...asRows<any>(searchIncidentsData?.incidentsList ?? searchIncidentsData).slice(0, 8).map((record: any) => ({
      id: `incident-${record.id}`,
      label: record.title || record.incident_type || "Boarding incident",
      detail: `${record.status || "open"} | ${record.severity || "normal"}`,
      view: "incidents" as ViewId,
    })),
  ];

  const searchResults = searchTerm.trim()
    ? searchRecords.filter((record) => `${record.label} ${record.detail}`.toLowerCase().includes(searchTerm.toLowerCase()))
    : [];

  useEffect(() => {
    function handleDashboardAction(event: Event) {
      const message = (event as CustomEvent<string>).detail;
      if (message) {
        toast.info(message);
      }
    }
    window.addEventListener("myshule-dashboard-action", handleDashboardAction);
    return () => window.removeEventListener("myshule-dashboard-action", handleDashboardAction);
  }, []);

  function openView(view: ViewId) {
    setActiveView(view);
    window.history.replaceState(null, "", buildSchoolSectionHref("boarding-master", view, routeMode ?? "hosted"));
  }

  function openSearchRecord(record: SearchRecord) {
    setActiveView(record.view);
    window.history.replaceState(null, "", buildSchoolSectionHref("boarding-master", record.view, routeMode ?? "hosted"));
    setSearchTerm("");
    toast.success(`Opened search result: ${record.label}`);
  }

  return (
    <div className="flex min-h-screen bg-[#F3F6FA]">
      {/* Sidebar */}
      <aside className="hidden h-screen w-[260px] overflow-y-auto bg-[#071D49] p-4 text-white shadow-[0_24px_70px_rgba(7,29,73,0.28)] lg:block shrink-0">
        <div className="rounded-2xl border border-white/10 bg-white/5 p-4 mb-6">
          <p className="text-xs font-black uppercase tracking-[0.22em] text-cyan-100/70">MyShule</p>
          <h2 className="mt-2 text-xl font-black">Boarding Master</h2>
          <p className="mt-2 text-sm leading-6 text-white/65">All Dormitories oversight.</p>
        </div>
        <nav className="space-y-1" aria-label="Boarding master navigation">
          {navItems.map((item, index) => {
            const showGroup = item.group !== navItems[index - 1]?.group;
            const Icon = item.icon;
            return (
              <div key={`${item.group}-${item.label}`}>
                {showGroup ? <p className="px-3 pb-2 pt-4 text-[10px] font-black uppercase tracking-[0.2em] text-white/40">{item.group}</p> : null}
                <button
                  type="button"
                  onClick={() => openView(item.id)}
                  className={cn(
                    "flex w-full items-center gap-3 rounded-xl px-3 py-2.5 text-left text-sm font-bold text-white/70 transition hover:bg-white/10 hover:text-white",
                    activeView === item.id && "bg-white/15 text-white shadow-[inset_4px_0_0_#38BDF8]",
                  )}
                >
                  <Icon className="h-4 w-4" aria-hidden="true" />
                  {item.label}
                </button>
              </div>
            );
          })}
        </nav>
      </aside>

      {/* Main Area */}
      <main className="flex-1 min-w-0 flex flex-col h-screen overflow-hidden">
        {/* Topbar */}
        <header className="sticky top-0 z-20 border-b border-[#D8E0EC] bg-white/90 px-4 py-3 backdrop-blur shrink-0">
          <div className="flex flex-col gap-3 xl:flex-row xl:items-center xl:justify-between">
            <div className="flex items-center gap-3">
              <div className="grid h-10 w-10 place-items-center rounded-xl bg-[#071D49] text-xs font-black text-white">BM</div>
              <div>
                <h1 className="text-lg font-black text-[#071D49]">Good Evening, Mr. Otieno</h1>
                <p className="text-xs font-bold text-[#64748B]">Boarding Master Ã¢â‚¬Â¢ Term 2, 2026 Ã¢â‚¬Â¢ Week 6 Ã¢â‚¬Â¢ All Dormitories</p>
              </div>
            </div>
            <div className="flex items-center gap-3">
               <div className="relative w-64 hidden md:block">
                 <Search className="absolute left-3 top-1/2 h-4 w-4 -translate-y-1/2 text-[#94A3B8]" />
                 <input 
                   value={searchTerm}
                   onChange={(e) => setSearchTerm(e.target.value)}
                   className="h-10 w-full rounded-xl border border-[#D8E0EC] pl-9 pr-4 text-sm outline-none focus:border-[#071D49]" 
                   placeholder="Search student, adm, dorm, room..." 
                 />
                 {searchTerm.trim() && searchResults.length > 0 && (
                   <div className="absolute top-[calc(100%+8px)] left-0 w-full bg-white border border-[#D8E0EC] rounded-xl shadow-xl z-30 p-2">
                     {searchResults.map(r => (
                       <button key={r.id} type="button" onClick={() => openSearchRecord(r)} className="w-full text-left p-2 hover:bg-[#F8FAFC] rounded-lg">
                         <p className="font-bold text-[#071D49] text-sm">{r.label}</p>
                         <p className="text-xs text-[#64748B]">{r.detail}</p>
                       </button>
                     ))}
                   </div>
                 )}
               </div>
                   <StatusChip label="Current school" tone="info" />
               <div className="flex items-center gap-2">
                 <TaskQueue />
                 <ApprovalInbox currentUserId="school" />
                 <NotificationBell />
               </div>
               <button type="button" onClick={() => openView("roll-call")} className="inline-flex h-10 items-center justify-center rounded-xl bg-[#071D49] px-4 text-sm font-black text-white">Start Roll Call</button>
            </div>
          </div>
          {/* Mobile Nav Selector */}
          <div className="mt-3 lg:hidden">
            <select
              className="h-10 w-full rounded-xl border border-[#D8E0EC] bg-white px-3 text-sm font-bold text-[#071D49] outline-none"
              value={activeView}
              onChange={(e) => openView(e.target.value as ViewId)}
            >
              {navItems.map((item) => (
                <option key={item.id} value={item.id}>{item.label}</option>
              ))}
            </select>
          </div>
        </header>

        {/* Content Area */}
        <div className="flex-1 overflow-y-auto p-4 lg:p-6">
          {activeView === "overview" && <OverviewWorkspace onNavigate={openView} />}
          {activeView === "register" && <RegisterWorkspace />}
          {activeView === "dorms" && <DormsWorkspace />}
          {activeView === "beds" && <BedsWorkspace />}
          {activeView === "roll-call" && <RollCallWorkspace />}
          {activeView === "leave" && <LeaveWorkspace />}
          {activeView === "late-returns" && <LateReturnsWorkspace />}
          {activeView === "duty" && <DutyWorkspace />}
          {activeView === "incidents" && <IncidentsWorkspace />}
          {activeView === "welfare" && <WelfareWorkspace />}
          {activeView === "meals" && <MealsWorkspace />}
          {activeView === "inspections" && <InspectionsWorkspace />}
          {activeView === "maintenance" && <MaintenanceWorkspace />}
          {activeView === "inventory" && <InventoryWorkspace />}
          {activeView === "visitors" && <VisitorsWorkspace />}
          {activeView === "communication" && <CommunicationWorkspace />}
          {activeView === "approvals" && <ApprovalsWorkspace />}
          {activeView === "reports" && <ReportsWorkspace />}
          {activeView === "settings" && <SettingsWorkspace />}
        </div>
      </main>
      
    </div>
  );
}
